package greeter

import "strings"

// Slug 把 name 转成适合做页面锚点的 URL 友好 slug：
// 大小写不敏感（统一小写）、空白折叠成单个连字符、首尾不留连字符。
func Slug(name string) string {
	return strings.Join(strings.Fields(strings.ToLower(name)), "-")
}
```

