package greeter

import "testing"

func TestSlug(t *testing.T) {
	cases := []struct {
		name string
		in   string
		want string
	}{
		{"single word", "Ada", "ada"},
		{"lowercases", "ADA LOVELACE", "ada-lovelace"},
		{"folds spaces", "Hello   World", "hello-world"},
		{"trims ends", "  Hello World  ", "hello-world"},
		{"folds tabs and newlines", "a\tb\nc", "a-b-c"},
		{"empty", "", ""},
		{"blank", "   ", ""},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			if got := Slug(tc.in); got != tc.want {
				t.Fatalf("Slug(%q) = %q, want %q", tc.in, got, tc.want)
			}
		})
	}
}

func TestSlugCaseInsensitive(t *testing.T) {
	if Slug("Hello World") != Slug("hELLO   wORLD") {
		t.Fatal("slug should be case- and whitespace-insensitive")
	}
}
```

